D=['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
def sp(x):
 return ' '.join(D[int(c)] for c in str(x) if c.isdigit())
def dg(s):
 return ''.join(c for c in str(s or '') if c.isdigit())
def nm(s):
 return str(s or '').replace('İ','i').replace('I','ı').lower().strip()
def mt(cn,said):
 cn=str(cn)
 if len(said)<len(cn):
  cn=cn[-len(said):]
 if len(cn)!=len(said):
  return False
 return all((not a.isdigit()) or a==z for a,z in zip(cn,said))
try:
 result.pop('header',None)
 b=result.get('data') if isinstance(result.get('data'),dict) else dict()
 bd=b.get('data') if isinstance(b.get('data'),dict) else None
 rc=str((b.get('result') or dict()).get('returnCode',''))
 if not (str(result.get('status_code'))=='200' and bd is not None and rc=='1'):
  vars['card_selected']='error'
  b['what_to_do_next']='Service error. Do not say anything.'
 else:
  cards=[c for c in (bd.get('cards') or []) if isinstance(c,dict)]
