  menu='; '.join((str(c.get('productName') or '').strip() or 'isimsiz kart')+', son dört hane '+sp(c.get('cardNumberLast4')) for c in cards)
  if noname:
   w='The caller named a card that is not in the list. Say there is no card with that name, read these cards and ask which one: '+menu
