M=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
O=['','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
T=['','on','yirmi','otuz','kırk','elli','altmış','yetmiş','seksen','doksan']
AP=chr(39)
def w3(n):
 h=n//100
 r=n%100
 s=''
 if h:
  s=('' if h==1 else O[h]+' ')+'yüz '
 if r//10:
  s+=T[r//10]+' '
 if r%10:
  s+=O[r%10]
 return s.strip()
def wd(n):
 if n==0:
  return 'sıfır'
 p=[]
 for v,u in ((10**9,'milyar'),(10**6,'milyon'),(1000,'bin')):
  q=n//v
  n=n%v
  if q:
   p.append('bin' if (v==1000 and q==1) else w3(q)+' '+u)
 if n:
  p.append(w3(n))
 return ' '.join(p)
def am(x,u,s):
 c=int(round(abs(float(x))*100))
 t=wd(c//100)+' '+u
 if c%100:
  t+=' '+wd(c%100)+' '+s
 return t
def ds(x):
 try:
  a=str(x).split('.')
  return str(int(a[0]))+' '+M[int(a[1])-1]+' '+a[2]
 except Exception:
  return ''
def f(x):
 try:
  return float(x)
 except Exception:
  return 0.0
for k in ['debt_text','followup_q','offer_text','followup_mode','has_debt']:
 if k not in vars:
  vars[k]=''
try:
 result.pop('header',None)
 b=result.get('data') if isinstance(result.get('data'),dict) else dict()
 bd=b.get('data') if isinstance(b.get('data'),dict) else None
 rc=str((b.get('result') or dict()).get('returnCode',''))
 if not (str(result.get('status_code'))=='200' and bd is not None and rc=='1'):
  vars['balance_state']='error'
  b['what_to_do_next']='Service error. Do not say anything.'
 else:
  L=str(vars.get('selected_last4') or '')
  N=str(vars.get('selected_name') or '')
  card='Sonu '+L+' ile biten '+(N+' ' if N else '')+'kartınız'
  sd=str(bd.get('statementDate') or '')
  vars['pdf_statement_date']=sd
  now=str(vars.get('now') or '')[:10]
  cur=(('TL','debtTL','Türk Lirası','kuruş'),('USD','debtUSD','Dolar','sent'),('EUR','debtEUR','Euro','sent'),('GBP','debtGBP','İngiliz Sterlini','peni'))
  lines=[]
  nod=[]
  first=''
  for code,key,cn,sub in cur:
   k=bd.get(key)
   if not isinstance(k,dict):
    continue
   rd=f(k.get('remainingDebt'))
   if rd<=0:
    nod.append(cn)
    continue
   if not first:
    first=code
   s0=f(k.get('statementDebt'))
   mp=f(k.get('minPayment'))
   rm=f(k.get('remainingMinPayment'))
   if code=='TL':
    if rm>=mp:
     s=cn+' borcunuz '+am(s0,cn,sub)+', ödenmesi gereken minimum tutar '+am(mp,cn,sub)+'.'
    elif rm<=0:
     s=cn+' borcunuz '+am(s0,cn,sub)+', kalan toplam borcunuz '+am(rd,cn,sub)+'. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
    else:
     s=cn+' borcunuz '+am(s0,cn,sub)+', ödenmesi gereken minimum tutar '+am(mp,cn,sub)+', kalan toplam borcunuz '+am(rd,cn,sub)+', kalan minimum ödeme tutarınız '+am(rm,cn,sub)+'.'
   else:
    s=cn+' borcunuz '+am(s0,cn,sub)+', kalan toplam borcunuz '+am(rd,cn,sub)+', ödenmesi gereken minimum tutar '+am(mp,cn,sub)+'.'
   lines.append(s)
  vars['pdf_currency']=first or 'TL'
  if lines:
   vars['has_debt']='yes'
   t=card+'a ait '+(ds(sd)+' tarihinde kesilen ' if sd else '')+'ekstre '+' '.join(lines)
   if nod:
    t+=' '+(nod[0] if len(nod)==1 else ', '.join(nod[:-1])+' ve '+nod[-1])+' borcunuz bulunmamaktadır.'
   tl=bd.get('debtTL')
   if str(bd.get('automaticPaymentFlag'))=='Y' and isinstance(tl,dict) and f(tl.get('remainAutomaticPaymentAmount'))>0:
    t+=' Otomatik ödeme talimatınızla ödenecek kalan tutar '+am(tl.get('remainAutomaticPaymentAmount'),'Türk Lirası','kuruş')+'.'
   lp=str(bd.get('lastPayDate') or '')
   if lp:
    a=lp.split('.')
    if len(a)==3 and now==a[2]+'-'+a[1]+'-'+a[0]:
     t+=' Borçlarınız için son ödeme tarihiniz bugündür.'
    else:
     sx=['dir','dir','dir','tür','tür','tir','dır','dir','dir','dur'][int(lp[-1])]
     t+=' Borçlarınız için son ödeme tarihiniz '+ds(lp)+AP+sx+'.'
  else:
   vars['has_debt']='no'
   t=card+('ın '+ds(sd)+' tarihli ekstresinden borcunuz bulunmamaktadır.' if sd else 'da ekstre borcunuz bulunmamaktadır.')
   tl=bd.get('debtTL')
   if isinstance(tl,dict) and f(tl.get('totalDebt'))>0:
    t+=' Gelecek dönemler dahil toplam borcunuz '+am(tl.get('totalDebt'),'Türk Lirası','kuruş')+'.'
   nd=str(bd.get('nextLastPayDate') or '')
   if nd and ds(nd):
    t+=' Son ödeme tarihiniz '+ds(nd)+' olacaktır.'
  vars['debt_text']=t
  offer='Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim. Hangisini istersiniz?' if vars.get('email_state')=='ok' else 'Hesap kesim tarihinizi değiştirebilirim. İster misiniz?'
  vars['offer_text']=offer
  try:
   cc=int(vars.get('card_count') or 1)
  except Exception:
   cc=1
  if cc>1:
   vars['followup_mode']='other_card'
   vars['followup_q']='Başka bir kartınızın borcunu öğrenmek ister misiniz?'
  elif lines:
   vars['followup_mode']='offer'
   vars['followup_q']=offer
  else:
   vars['followup_mode']='end'
   vars['followup_q']=''
  vars['balance_state']='ok'
  b['what_to_do_next']='Debt text is ready. Do not add anything.'
except Exception:
 vars['balance_state']='error'

